@dataclass(frozen=True)
class ColdRestartSpec:
    """Explicit three-RESET cold path, preserving the actual driver IRQ clock."""
    reset_pulse_clocks: tuple[int, int, int]
    irq_clock_hz: int
    startup_im1_offsets: tuple[int, int, int]

    def __post_init__(self):
        if type(self.reset_pulse_clocks) is not tuple or len(self.reset_pulse_clocks) != 3 or any((type(value) is not int or value < 3 for value in self.reset_pulse_clocks)):
            raise ValueError('three explicit finite cold RESET pulse grants of at least3 required')
        if type(self.irq_clock_hz) is not int or self.irq_clock_hz <= 0:
            raise ValueError('explicit matching positive driver IRQ frequency required')
        if type(self.startup_im1_offsets) is not tuple or len(self.startup_im1_offsets) != 3 or any((type(value) is not int or value <= 0 for value in self.startup_im1_offsets)) or any((left >= right for left, right in zip(self.startup_im1_offsets, self.startup_im1_offsets[1:]))):
            raise ValueError('three explicit strictly increasing positive startup IM1 offsets required')


@dataclass(frozen=True)
class OrderedRestartPlan:
    """Declare a protocol and real reset path; do not force a game branch."""
    kind: str
    supply: IntroRestartSpec | ColdRestartSpec
    reset_path: str = 'warm'

    def __post_init__(self):
        if type(self.kind) is not str or self.kind not in ('intro', 'narrative') or type(self.reset_path) is not str or (self.reset_path not in ('warm', 'cold')):
            raise ValueError('explicit intro/narrative protocol and warm/cold path required')
        expected = IntroRestartSpec if self.reset_path == 'warm' else ColdRestartSpec
        if type(self.supply) is not expected:
            raise ValueError('the exact explicitly declared warm2/cold3 supply type is required')


def _dump(node):
    return ast.dump(node, include_attributes=False)


def _code_shape(code):
    return tuple(getattr(code, name) for name in (
        'co_code', 'co_names', 'co_varnames', 'co_argcount', 'co_posonlyargcount',
        'co_kwonlyargcount', 'co_flags', 'co_freevars', 'co_cellvars')) + (tuple(
            _code_shape(value) if type(value) is CodeType else value for value in code.co_consts),)


def _named_code(code, name):
    rows = [value for value in code.co_consts if type(value) is CodeType and value.co_name == name]
    if len(rows) != 1:
        raise Boundary('one complete original ordered-reset source code required: ' + name)
    return rows[0]


def _ordered_attribute_tree(kind, original):
    """Invert all nine attribute substitutions and the entire two source modules."""
    if kind not in METHOD_SPECS or _dump(original) != EXPECTED_PROTOCOL_AST[kind]:
        raise Boundary('the complete original distinct restart protocol source is required')
    classes = [node for node in original.body if isinstance(node, ast.ClassDef) and node.name == PROTOCOL_CLASSES[kind]]
    if len(classes) != 1:
        raise Boundary('one actual complete original restart class required')
    cls = classes[0]
    result = copy.deepcopy(original)
    result_class = result.body[original.body.index(cls)]
    inverses = {}
    for index, method in enumerate(cls.body):
        if not isinstance(method, ast.FunctionDef) or method.name not in METHOD_SPECS[kind]:
            continue
        spec = METHOD_SPECS[kind][method.name]
        counts = {key: 0 for key in spec}

        class Lift(ast.NodeTransformer):

            def visit_Attribute(self, node):
                node = self.generic_visit(node)
                if isinstance(node.value, ast.Name) and (node.value.id, node.attr) in spec:
                    key = (node.value.id, node.attr)
                    counts[key] += 1
                    node.attr = spec[key][1]
                return node
        derived = Lift().visit(copy.deepcopy(method))
        if counts != {key: value[0] for key, value in spec.items()}:
            raise Boundary('exact ordered-reset identity substitutions differ: ' + method.name)
        undo = {key: 0 for key in spec}

        class Inverse(ast.NodeTransformer):

            def visit_Attribute(self, node):
                node = self.generic_visit(node)
                for (carrier, before), (_, after) in spec.items():
                    if isinstance(node.value, ast.Name) and node.value.id == carrier and (node.attr == after):
                        undo[carrier, before] += 1
                        node.attr = before
                        break
                return node
        inverse = Inverse().visit(copy.deepcopy(derived))
        if undo != counts or _dump(inverse) != _dump(method):
            raise Boundary('whole original lifecycle method inverse differs: ' + method.name)
        result_class.body[index] = derived
        inverses[index] = inverse
    if len(inverses) != len(METHOD_SPECS[kind]):
        raise Boundary('all original lifecycle methods are required')
    restored = copy.deepcopy(result)
    for index, method in inverses.items():
        restored.body[original.body.index(cls)].body[index] = method
    if _dump(restored) != _dump(original):
        raise Boundary('whole original restart source module inverse differs')
    return ast.fix_missing_locations(result)


def _replace_exact_fragment(tree, before, after):
    """Replace one complete AST node or sibling statement block, never a shape."""
    matches = 0

    def rewrite(value):
        nonlocal matches
        if isinstance(before, list) and isinstance(value, list):
            result = []
            index = 0
            while index < len(value):
                if index + len(before) <= len(value) and all((_dump(left) == _dump(right) for left, right in zip(value[index:index + len(before)], before))):
                    matches += 1
                    result.extend(copy.deepcopy(after))
                    index += len(before)
                else:
                    result.append(rewrite(value[index]))
                    index += 1
            return result
        if isinstance(value, ast.AST):
            if not isinstance(before, list) and _dump(value) == _dump(before):
                matches += 1
                return copy.deepcopy(after)
            for field, child in ast.iter_fields(value):
                if isinstance(child, (ast.AST, list)):
                    setattr(value, field, rewrite(child))
            return value
        if isinstance(value, list):
            return [rewrite(child) for child in value]
        return value
    result = rewrite(copy.deepcopy(tree))
    if matches != 1:
        raise Boundary('one complete exact ordered-reset source fragment required; found ' + str(matches))
    return result


def _ordered_protocol_tree(kind, original, *, reset_path='warm'):
    """Keep both whole protocols; invert each explicit cold/lifetime delta."""
    stage = _ordered_attribute_tree(kind, original)
    if reset_path not in ('warm', 'cold'):
        raise Boundary('an explicit reset source path is required')
    cls = next((node for node in stage.body if isinstance(node, ast.ClassDef) and node.name == PROTOCOL_CLASSES[kind]))
    method = next((node for node in cls.body if isinstance(node, ast.FunctionDef) and node.name == 'complete_transfer'))
    changed = copy.deepcopy(method)
    edits = []

    def expression(before, after):
        edits.append((ast.parse(before, mode='eval').body, ast.parse(after, mode='eval').body))

    def statements(before, after):
        edits.append((ast.parse(before).body, ast.parse(after).body))
    expression('self.pulse_start + 2 * self.consumed', 'self._pulse_offset(0)')
    expression('self.pulse_start + 2 * (self.consumed + 1)', 'self._pulse_offset(1)')
    if reset_path == 'cold':
        expression('self._' + kind + '_guard(driver)', 'self._cold_' + kind + '_guard(driver)')
        statements('frame = self.' + kind + '_programs.claim(jump)', 'cold_claim = capture_cold_reset_claim(jump)\nframe = self.' + kind + '_programs.claim(jump)')
        statements('capture = WarmDriverInstallationCapture(self.rig.sound, self.rig.control, self.rig.source, reset_session=reset, retirement=retired, jump=jump)', 'capture = self._cold_capture(reset, retired, jump, cold_claim)')
        statements("waiting = reset.start()\nif type(waiting) is not BootstrapMainWait or waiting.poll != 0x3BC:\n    raise Boundary('actual reentry chose cold audio-release work; explicit cold authority is required')\ninstallation = capture.finish(waiting)", 'waiting, installation, cold_frame = self._resume_cold(reset, capture, retired, jump, plan)')
        statements('authority = DriverInstalledAuthority(installation, retired.frame)', 'authority = DriverInstalledAuthority(installation, cold_frame)')
    for before, after in edits:
        changed = _replace_exact_fragment(changed, before, after)
    inverse = copy.deepcopy(changed)
    for before, after in reversed(edits):
        inverse = _replace_exact_fragment(inverse, after, before)
    if _dump(inverse) != _dump(method):
        raise Boundary('whole retained cold/warm lifecycle inverse differs')
    result = copy.deepcopy(stage)
    result_cls = result.body[stage.body.index(cls)]
    result_cls.body[cls.body.index(method)] = changed
    restored = copy.deepcopy(result)
    restored.body[stage.body.index(cls)].body[cls.body.index(method)] = inverse
    if _dump(restored) != _dump(stage):
        raise Boundary('whole retained protocol source-module inverse differs')
    return ast.fix_missing_locations(result)


class OrderedRestartOwner:
    """One same-App sequence, one pulse ledger, two exact real transfer protocols."""

    def __init__(self, app, *, plans):
        from .application import GameApplication
        if type(app) is not GameApplication or app.operations != 0:
            raise ValueError('one fresh exact GameApplication before any operation required')
        app._live()
        if type(plans) is not tuple or not plans or len(plans) > 256 or any((type(plan) is not OrderedRestartPlan for plan in plans)):
            raise ValueError('one explicit nonempty finite ordered tuple of at most256 exact plans required')
        if any((getattr(app, name, None) is not None for name in ('intro_restarts', 'narrative_restarts', 'ordered_restarts'))) or any((getattr(app.scene_driver, name, None) is not None for name in ('_intro_restart_owner', '_narrative_restart_owner', '_ordered_restart_owner'))) or getattr(app.rig.interrupt_runtime, '_intro_reset_owner', None) is not None:
            raise Boundary('one ordered plan is mutually exclusive with existing restart owners and IRQ bindings')
        if type(app.audio) is not OwnedGameAudio or type(app.scene_driver) is not IntegratedSceneDriver:
            raise Boundary('actual retained cold-created audio and integrated Main required')
        app.audio._require_owned()
        schedule = app.rig.hardware_schedule
        supplies = tuple((row.supply for row in plans))
        if not isinstance(schedule, FinitePulseSoundSchedule) or schedule.owner is not app.rig.control or schedule._pulse is not None or (schedule._pulse_index != len(schedule.reset_pulse_clocks)) or any((row.irq_clock_hz != app.audio._loop.irq_clock_hz for row in supplies)):
            raise Boundary('completed cold pulse phase and explicitly matching future IRQ frequency required')
        self.app, self.rig, self.state = (app, app.rig, app.rig.scene)
        self.thread, self.active, self.failed = (threading.get_ident(), False, False)
        self.steps, self.plans, self.consumed, self.events = (plans, supplies, 0, [])
        self._declared_steps, self._declared_supplies = (plans, supplies)
        self.driver, self.schedule = (app.scene_driver, schedule)
        self.pulse_start = schedule._pulse_index
        offsets = [0]
        for row in supplies:
            offsets.append(offsets[-1] + len(row.reset_pulse_clocks))
        self.pulse_offsets = tuple(offsets)
        self._declared_pulse_offsets = self.pulse_offsets
        self.pulses = schedule.reset_pulse_clocks + tuple((value for row in supplies for value in row.reset_pulse_clocks))
        self.hardware, self.ram, self.data = (self.state.hardware, self.state.ram, self.state.data)
        self.source, self.save_image, self.save_backing = (self.rig.source, app.config.save_image, app.config.save_image.backing)
        self.sound, self.audio_state, self.control = (self.rig.sound, self.rig.audio, self.rig.control)
        self.fm, self.psg, self.memory = (self.rig.fm, self.rig.psg, self.rig.memory)
        self.outputs, self.fm_sink, self.psg_sink = (app.outputs, self.rig.fm.pcm_sink, self.rig.psg.pcm_sink)
        self.intro_programs, self.narrative_programs = (IntroIrqPrograms(self.state), None)
        self._make_views()
        bind_intro_irq(self.rig.interrupt_runtime, self.intro_programs)
        schedule.reset_pulse_clocks = self.pulses
        self.driver._ordered_restart_owner = self
        app.ordered_restarts = self

    def _make_views(self):
        self.modules = {kind: importlib.import_module(path) for kind, path in PROTOCOL_MODULES.items()}
        self.views, self.originals, self.globals = ({}, {}, {})
        self.extra_globals = {}
        for kind, module in self.modules.items():
            tree = ast.parse(inspect.getsource(module), filename=module.__file__)
            if _dump(tree) != EXPECTED_PROTOCOL_AST[kind]:
                raise Boundary('complete original restart module changed: ' + kind)
            plain = _named_code(compile(tree, module.__file__, 'exec', dont_inherit=True), PROTOCOL_CLASSES[kind])
            cls = getattr(module, PROTOCOL_CLASSES[kind])
            for name in METHOD_SPECS[kind]:
                original = vars(cls).get(name)
                if type(original) is not FunctionType or original.__globals__ is not vars(module) or original.__qualname__ != PROTOCOL_CLASSES[kind] + '.' + name or (original.__closure__ is not None) or original.__code__.co_freevars or (_code_shape(original.__code__) != _code_shape(_named_code(plain, name))):
                    raise Boundary('actual complete original lifecycle method required: ' + kind + ':' + name)
                self.originals[kind, name] = (cls, original, original.__code__)
            for path in ('warm', 'cold'):
                derived = _named_code(compile(_ordered_protocol_tree(kind, tree, reset_path=path), module.__file__, 'exec', dont_inherit=True), PROTOCOL_CLASSES[kind])
                namespace = dict(vars(module))
                if path == 'cold':
                    if 'capture_cold_reset_claim' in namespace:
                        raise Boundary('private cold claim binding must not shadow the original namespace')
                    namespace['capture_cold_reset_claim'] = capture_cold_reset_claim
                    self.extra_globals[kind, path, 'capture_cold_reset_claim'] = (namespace, capture_cold_reset_claim)
                for name in METHOD_SPECS[kind]:
                    if path == 'cold' and name != 'complete_transfer':
                        continue
                    original = self.originals[kind, name][1]
                    view = FunctionType(_named_code(derived, name), namespace, name, original.__defaults__, None)
                    view.__kwdefaults__, view.__annotations__ = (original.__kwdefaults__, dict(original.__annotations__))
                    self.views[kind, path, name] = view
                    for global_name in view.__code__.co_names:
                        if global_name in vars(module):
                            self.globals[kind, path, global_name] = (namespace, namespace[global_name])
        self.view_owners = dict(self.views)
        self.view_codes = {key: view.__code__ for key, view in self.views.items()}

    def _require_sources(self):
        for (kind, name), (cls, original, code) in self.originals.items():
            if getattr(self.modules[kind], PROTOCOL_CLASSES[kind]) is not cls or vars(cls).get(name) is not original or original.__code__ is not code:
                raise Boundary('original distinct lifecycle callable was rebound')
        if self.views.keys() != self.view_owners.keys():
            raise Boundary('ordered lifecycle view set changed')
        for key, view in self.view_owners.items():
            if self.views[key] is not view or view.__code__ is not self.view_codes[key]:
                raise Boundary('complete ordered lifecycle view changed')
        for (kind, path, name), (namespace, value) in self.globals.items():
            if namespace.get(name) is not value or vars(self.modules[kind]).get(name) is not value:
                raise Boundary('original lifecycle/capture dependency binding was changed: ' + name)
        for (kind, path, name), (namespace, value) in self.extra_globals.items():
            if namespace.get(name) is not value or value is not capture_cold_reset_claim:
                raise Boundary('actual retained cold-claim source binding changed')

    def _guard(self, driver, kind):
        self._require_sources()
        if type(self) is not OrderedRestartOwner or self.failed or self.active or (threading.get_ident() != self.thread) or self.app.closed or self.app.failed or (self.app.rig is not self.rig) or (self.app.scene_driver is not driver) or (driver is not self.driver) or (driver.rig is not self.rig) or (driver.state is not self.state) or (getattr(driver, '_ordered_restart_owner', None) is not self) or (getattr(self.app, 'ordered_restarts', None) is not self) or (getattr(self.app, 'intro_restarts', None) is not None) or (getattr(self.app, 'narrative_restarts', None) is not None) or (getattr(driver, '_intro_restart_owner', None) is not None) or (getattr(driver, '_narrative_restart_owner', None) is not None) or (self.steps is not self._declared_steps) or (self.plans is not self._declared_supplies or self.pulse_offsets is not self._declared_pulse_offsets) or (self.rig.hardware_schedule is not self.schedule) or (self.schedule.reset_pulse_clocks is not self.pulses) or (getattr(self.rig.interrupt_runtime, '_intro_reset_owner', None) is not self.intro_programs) or (self.state.hardware is not self.hardware) or (self.state.ram is not self.ram) or (self.state.data is not self.data) or (self.rig.source is not self.source) or (self.source.data is not self.data) or (self.app.config.save_image is not self.save_image) or (self.save_image.backing is not self.save_backing) or (self.rig.sound is not self.sound) or (self.rig.audio is not self.audio_state) or (self.rig.control is not self.control) or (self.rig.fm is not self.fm) or (self.rig.psg is not self.psg) or (self.rig.memory is not self.memory) or (self.app.outputs is not self.outputs) or (self.fm.pcm_sink is not self.fm_sink) or (self.psg.pcm_sink is not self.psg_sink):
            raise Boundary('one unchanged ordered application/Scene/device/source/save/PCM ownership required')
        self.rig.require_live()
        self.intro_programs._guard()
        if self.consumed >= len(self.steps):
            raise Boundary('explicit ordered reset plan exhausted; no automatic refill')
        if self.steps[self.consumed].kind != kind:
            raise Boundary('actual ' + kind + ' transfer does not match next declared ordered kind ' + self.steps[self.consumed].kind)

    def _intro_guard(self, driver):
        self._guard(driver, 'intro')
        self._require_selected_path('warm')

    def _narrative_guard(self, driver):
        self._guard(driver, 'narrative')
        self._require_selected_path('warm')

    def _ordered_validate_transfer(self, driver, before, jump, request, accepted_irq_result):
        self._require_sources()
        return self.views['narrative', 'warm', '_validate_transfer'](self, driver, before, jump, request, accepted_irq_result)

    def complete_transfer(self, driver, before, request, accepted_irq_result, error):
        if type(request) is not InterruptRequest:
            raise Boundary('actual typed interrupt request required for ordered reset dispatch')
        if type(error) is OriginalIntroResetJump:
            self._guard(driver, 'intro')
            if accepted_irq_result is not None or error.owner is not self.intro_programs:
                raise Boundary('intro JMP must abandon this original IRQ without an accepted RTE result')
            path = self.steps[self.consumed].reset_path
            return self.views['intro', path, 'complete_transfer'](self, driver, before, error, request)
        if type(error) is OriginalNarrativeResetJump:
            self._guard(driver, 'narrative')
            path = self.steps[self.consumed].reset_path
            return self.views['narrative', path, 'complete_transfer'](self, driver, before, error, request, accepted_irq_result)
        raise error

    def diagnostics(self):
        if threading.get_ident() != self.thread:
            raise Boundary('ordered reset diagnostics belong to the owning application thread')
        return dict(failed=self.failed, active=self.active, completed=self.consumed, remaining=len(self.steps) - self.consumed, next_kind=None if self.consumed == len(self.steps) else self.steps[self.consumed].kind, next_reset_path=None if self.consumed == len(self.steps) else self.steps[self.consumed].reset_path, completed_kinds=[row.kind for row in self.steps[:self.consumed]], completed_reset_paths=[row.reset_path for row in self.steps[:self.consumed]], declared_pulse_offsets=list(self.pulse_offsets), actual_intro_jumps=self.intro_programs.jumps, consumed_reset_pulses=self.schedule._pulse_index - self.pulse_start, declared_reset_pulses=len(self.pulses) - self.pulse_start, last_event=None if not self.events else self.events[-1], last_actual_cold_installation=getattr(self, 'last_cold_installation', None), original_game_bug_fixes=0, runtime_acceptance_claimed=False)

    def _pulse_offset(self, following):
        if type(following) is not int or following not in (0, 1):
            raise Boundary('current or next actual declared pulse boundary required')
        if self.pulse_offsets is not self._declared_pulse_offsets or not 0 <= self.consumed + following < len(self.pulse_offsets):
            raise Boundary('unchanged finite actual reset-pulse ledger required')
        return self.pulse_start + self.pulse_offsets[self.consumed + following]

    def _require_selected_path(self, expected):
        if self.steps[self.consumed].reset_path != expected:
            raise Boundary('actual lifecycle is not the explicitly declared ' + expected + ' reset path')

    def _cold_intro_guard(self, driver):
        self._guard(driver, 'intro')
        self._require_selected_path('cold')

    def _cold_narrative_guard(self, driver):
        self._guard(driver, 'narrative')
        self._require_selected_path('cold')

    def _cold_capture(self, reset, retired, jump, claim):
        """Bind this actual post-retirement invocation before original206 runs."""
        from ..high_level_audio_engine.retained_cold_workspace import RetainedColdWorkspaceCopyAuthority
        authority = RetainedColdWorkspaceCopyAuthority(self.sound, self.control, self.source, reset_session=reset, retirement=retired, jump=jump, claim=claim)
        self.last_cold_authority = authority
        return authority

    def _resume_cold(self, reset, authority, retired, jump, plan):
        """Run actual workspace, then the same206 tail and real driver install."""
        from ..high_level_audio_engine.cold_workspace import ColdWorkspaceSession
        from ..high_level_audio_engine.retained_cold_workspace import handoff_retained_cold_platform
        from ..high_level_audio_engine.city_driver_installation import CityDriverInstallationCapture
        from ..high_level_audio_engine.platform_handoff import handoff_expired_cold_platform
        from ..high_level_main_flows.bootstrap_reset import ResetAudioReleasePoint
        from ..high_level_main_flows.bootstrap_steps import BootstrapMainWait
        cold = None
        try:
            release = reset.start()
            if type(release) is not ResetAudioReleasePoint or release.session is not reset or reset.waiting is not release or (reset.phase != 'actual-audio-release') or (release.pc != 610):
                raise Boundary('declared cold path must actually reach this original260/262 release')
            authority.finish(release)
            handoff = handoff_retained_cold_platform(self.sound, self.control, authority=authority)
            handoff.require_attached(self.sound, self.control)
            platform = self.audio_state.platform
            lease = self.control.acquire_frame('startup', 0, authority=authority)
            self.last_cold_startup_lease = lease
            cold = ColdWorkspaceSession(self.sound, self.control, lease)
            self.last_cold_session = cold
            idle = cold.start()
            if reset.waiting is not release or self.state.sr != release.full_sr:
                raise Boundary('cold workspace changed the actual suspended68000 reset continuation')
            capture = CityDriverInstallationCapture(self.sound, self.control, self.source, reset_session=reset)
            self.last_capture = capture
            waiting = reset.resume_release(release)
            if type(waiting) is not BootstrapMainWait or waiting.poll != 956:
                raise Boundary('same cold206 invocation did not reach its original first Main3BC')
            installation = capture.finish(waiting)
            attached = handoff_expired_cold_platform(self.sound, self.control, expired_cold_session=cold, installation=installation, refresh_reader=platform.refresh_reader, memory_bit_reader=platform.memory_bit_reader)
            attached.require_attached(self.sound, self.control)
            evidence = dict(status='actual_cold_workspace_and_driver_installation', source_pc=jump.source_pc, old_epoch=retired.reset_epoch, new_epoch=self.sound.reset_epoch, actual_workspace_idle_pc=idle.pc, actual_idle_frame_used=True, original_release_pc=release.pc, same_Scene_RAM_DATA_devices_save_and_PCM=True, runtime_acceptance_claimed=False)
            self.rig.source_contract.setdefault('actual_retained_cold_installations', []).append(evidence)
            self.last_cold_installation = evidence
            return (waiting, installation, idle.frame)
        except BaseException as error:
            try:
                if cold is not None:
                    cold.failed = True
                    self.control.abandon_frame_session(cold, reason='actual retained cold lifecycle boundary')
            except BaseException as cleanup:
                error.add_note('Actual retained cold software cleanup: ' + str(cleanup))
            raise


def handle_ordered_restart_transfer(driver, before, request, accepted_irq_result, error):
    """Only the existing actual IRQ exception path calls this closed dispatcher."""
    owner = getattr(driver, '_ordered_restart_owner', None)
    if type(owner) is not OrderedRestartOwner \
            or type(error) not in (OriginalIntroResetJump, OriginalNarrativeResetJump):
        driver.failed = True
        raise error
    try:
        return owner.complete_transfer(driver, before, request, accepted_irq_result, error)
    except BaseException:
        owner.failed = driver.failed = True
        raise


def enable_ordered_restarts(app, *, plans):
    """Opt in once on a fresh App; no old owner is created, detached or rebound."""
    return OrderedRestartOwner(app, plans=plans)
